#include <iostream>

int main() {
    int temperature;
    if (!(std::cin >> temperature) || temperature < -50 || temperature > 50) {
        std::cout << "invalid\n";
        return 0;
    }
    if (temperature < 10) std::cout << "cold\n";
    else if (temperature <= 25) std::cout << "comfortable\n";
    else std::cout << "hot\n";
}

